from flask import Blueprint, jsonify, request

from app.repository import UserRepository

users_bp = Blueprint("users", __name__)
_repo = UserRepository()


@users_bp.post("/users")
def create_user():
    data = request.get_json(silent=True) or {}
    user = _repo.add(data.get("username"), data.get("password"))
    # BUG: returns the repository dict, which includes password_hash.
    return jsonify(user), 201


@users_bp.get("/users/<int:uid>")
def get_user(uid):
    user = _repo.get(uid)
    if user is None:
        return jsonify({"error": "not found"}), 404
    # BUG: same leak on the read path.
    return jsonify(user)

